<?php require __DIR__.'/_auth.php'; ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Horários · Larissa Beauty</title><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Montserrat:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/admin.css"></head><body><div class="app"><nav class="menu"><a class="marca" href="dashboard.php">Larissa Beauty</a><a class="link" href="dashboard.php">Início</a><a class="link" href="agenda.php">Agenda</a><a class="link" href="servicos.php">Serviços</a><a class="link on" href="horarios.php">Horários</a><a class="link sair" href="#" id="sair">Sair</a></nav><main class="conteudo"><div class="cabeca"><div><h1>Horários</h1><p>Horários fixos de atendimento e bloqueios da agenda.</p></div></div><div class="lista" id="fixos"><div class="item simples"><div><span class="nome">10:00 · 12:00 · 14:00 · 16:00 · 18:00</span><small>Horários fixos configurados no sistema.</small></div></div></div><h2 style="margin-top:36px">Bloquear dia ou horário</h2><form class="form-linha" id="bloq" style="grid-template-columns:1fr 1fr 1.5fr auto;margin-top:14px"><label>Data<input type="date" name="data" required></label><label>Horário<select name="hora"><option value="">Dia inteiro</option><option>10:00</option><option>12:00</option><option>14:00</option><option>16:00</option><option>18:00</option></select></label><label>Motivo (opcional)<input name="motivo" placeholder="Ex.: compromisso"></label><button class="btn">Bloquear</button></form><p id="msg" class="resumo"></p><h2>Datas bloqueadas</h2><div class="lista" id="dias"><div class="vazio">Carregando...</div></div><h2 style="margin-top:28px">Horários bloqueados</h2><div class="lista" id="horas"></div></main></div><script>
const apiBase='../backend/api/';async function call(file,data){const me=await fetch(apiBase+'me.php',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json());if(!me.csrf)throw Error('Sessão expirada. Entre novamente.');const r=await fetch(apiBase+file,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':me.csrf},body:JSON.stringify(data)});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.erro||'Erro ('+r.status+')');return d;}const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR');
async function load(){try{const r=await fetch(apiBase+'listar_bloqueios.php',{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.erro||'Erro');document.getElementById('dias').innerHTML=d.dias.length?d.dias.map(x=>`<div class="item simples"><div><span class="nome">${fmt(x.data)}</span><small>${esc(x.motivo||'Sem motivo informado')}</small></div><button class="btn perigo" data-dia="${x.data}">Desbloquear</button></div>`).join(''):'<div class="vazio">Nenhum dia bloqueado.</div>';document.getElementById('horas').innerHTML=d.horarios.length?d.horarios.map(x=>`<div class="item simples"><div><span class="nome">${fmt(x.data)} · ${x.hora}</span><small>${esc(x.motivo||'Sem motivo informado')}</small></div><button class="btn perigo" data-data="${x.data}" data-hora="${x.hora}">Desbloquear</button></div>`).join(''):'<div class="vazio">Nenhum horário bloqueado.</div>';}catch(e){document.getElementById('dias').innerHTML='<div class="vazio">'+esc(e.message)+'</div>';}}
document.getElementById('bloq').addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const file=d.hora?'bloquear_horario.php':'bloquear_dia.php';try{await call(file,d);document.getElementById('msg').textContent='Bloqueio salvo no banco.';e.target.reset();load();}catch(x){document.getElementById('msg').textContent=x.message;}});document.getElementById('dias').addEventListener('click',async e=>{const b=e.target.closest('[data-dia]');if(!b)return;try{await call('desbloquear_dia.php',{data:b.dataset.dia});load();}catch(x){alert(x.message);}});document.getElementById('horas').addEventListener('click',async e=>{const b=e.target.closest('[data-data]');if(!b)return;try{await call('desbloquear_horarios.php',{data:b.dataset.data,hora:b.dataset.hora});load();}catch(x){alert(x.message);}});document.getElementById('sair').onclick=async e=>{e.preventDefault();try{await call('logout.php',{});}finally{location.href='login.php';}};load();</script></body></html>